#include <iostream>
#include <fstream>
#include <algorithm>
using namespace std;

int main() {
    ifstream plik("boki.txt");
    int n;
    plik >> n;
    for (int i = 0; i < n; i++) {
        int s[3];
        plik >> s[0] >> s[1] >> s[2];
        sort(s, s + 3);
        cout << "Trojkat " << i + 1 << " (" << s[0] << "," << s[1] << "," << s[2] << "): ";
        if (s[0] + s[1] <= s[2]) {
            cout << "nie jest trojkatem" << endl;
        } else if (s[0] * s[0] + s[1] * s[1] == s[2] * s[2]) {
            cout << "prostokatny" << endl;
        } else if (s[0] * s[0] + s[1] * s[1] > s[2] * s[2]) {
            cout << "ostrokatny" << endl;
        } else {
            cout << "rozwartokatny" << endl;
        }
    }
    return 0;
}
```

